mapper.update:
update goodscollection.review
set praise=#{praise}
where reviewId=#{reviewId}

mapper.select:
select praise
from goodscollection.review
where reviewId=#{reviewId}

select reviewId
from goodscollection.thumbsup
where userId=#{userId} and reviewId=#{reviewId}

select reviewId
from goodscollection.review
where goodsId=#{goodsId} and userId=#{userId}

select reviewimg.imgUrl
from goodscollection.reviewimg
where reviewId=#{reviewId}

select avg(scores)
from goodscollection.review
where goodsId=#{goodsId}
